{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-05",
  "sketch": {
    "components": ["Support deletion workflow", "Main database (deleted flag)", "Data warehouse", "Application logs", "Backups"],
    "dataStores": ["Main database", "Data warehouse", "Log store", "Backups"],
    "externalServices": [],
    "trustBoundaries": ["Customer to support intake", "Main database to warehouse/log pipeline"],
    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Deleted customers' personal data still readable in warehouse, logs and backups",
      "scenario": "A customer asks for account deletion and the main database row is only flagged. Anyone with warehouse, log or backup access (analysts, support, an attacker who obtains a warehouse credential or a backup file) can still read and export the full personal data of people who believed they were deleted. There is no propagation of the deletion to those copies, so the exposure is permanent and grows with every deletion request.",
      "component": "Data warehouse, logs and backups",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Copies in the warehouse, logs and backups are left as is." }
      ],
      "cwe": ["CWE-212", "CWE-359"],
      "plainLanguage": "When a customer asks to be deleted, their details are still sitting in the reporting database, the logs and the backups.",
      "requirement": {
        "title": "Propagate deletion to every copy of customer data",
        "given": "a customer's deletion request has been accepted",
        "when": "the deletion is executed",
        "then": "the personal data is erased or irreversibly anonymised in the main database, the warehouse and logs, and backups are covered by a documented retention window after which the data is gone, with the completion of each step recorded against the request"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Anyone can impersonate a customer and have their account deleted",
      "scenario": "The design describes requests arriving and support acting on them, with no identity verification of the requester. An attacker who knows a customer's email or account number sends a deletion request; support marks the account deleted and the real customer loses access to their account and service. The same path also lets an attacker probe which accounts exist.",
      "component": "Deletion request intake",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Customers can request account deletion. Support marks the account as deleted in the main database." }
      ],
      "cwe": ["CWE-287", "CWE-640"],
      "plainLanguage": "Someone could pretend to be a customer and get that customer's account wiped.",
      "requirement": {
        "title": "Verify the requester before accepting a deletion request",
        "given": "a deletion request for an account",
        "when": "support processes it",
        "then": "the request is only executed after the requester has proven control of the account (authenticated session plus a confirmation link or code sent to the registered contact), and the verification evidence is stored with the request"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Any support agent can delete any account with no approval or limits",
      "scenario": "A single support agent (or an attacker who phishes one support login) can mark arbitrary accounts as deleted in the main database. Nothing in the design restricts which accounts an agent may act on, requires a second approver for bulk actions, or caps volume, so one compromised or malicious insider account can destroy service for many customers at once.",
      "component": "Support deletion tooling",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "Support marks the account as deleted in the main database." }
      ],
      "cwe": ["CWE-285", "CWE-269"],
      "plainLanguage": "One support account, if misused or stolen, could delete lots of customers' accounts.",
      "requirement": {
        "title": "Restrict and gate the deletion action",
        "given": "a support agent using the deletion tooling",
        "when": "they execute a deletion, or more deletions than a defined threshold in a time window",
        "then": "the action is permitted only for agents holding a dedicated deletion role, is scoped to the account named in a verified request, and anything above the threshold requires a second authorised approver"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No record of who asked for a deletion or who carried it out",
      "scenario": "The design records only a deleted state on the account. When a customer later complains their account was wiped, or a regulator asks for proof that an erasure request was honoured, there is no evidence of who requested it, who approved it, when it ran, or which stores were covered. Disputes cannot be resolved and a malicious insider's deletions are indistinguishable from legitimate ones.",
      "component": "Deletion request record",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        { "quote": "Customers can request account deletion. Support marks the account as deleted in the main database." }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Nothing records who asked for a deletion or who pressed the button, so arguments about it can't be settled.",
      "requirement": {
        "title": "Keep a tamper-resistant deletion request ledger",
        "given": "a deletion request",
        "when": "it is received, verified, executed or rejected",
        "then": "an append-only record stores the requester, verification method, acting agent, timestamp, target account identifier and the outcome per data store, retained for the statutory period and not editable by support agents"
      }
    },
    {
      "stride": "Tampering",
      "title": "A soft-delete flag can be flipped back, resurrecting a deleted account",
      "scenario": "Because deletion is only a flag on the main database row, anyone with write access to that row (a support agent, a DBA, or an attacker exploiting an admin endpoint) can clear the flag and restore a deleted account, along with its sessions, payment instruments and contact details. The customer who asked to be removed is silently brought back into the system and may start receiving communications again.",
      "component": "Main database (deleted flag)",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Support marks the account as deleted in the main database." }
      ],
      "cwe": ["CWE-285"],
      "plainLanguage": "Deletion is just a checkbox, so someone can untick it and bring the account back.",
      "requirement": {
        "title": "Make deletion irreversible after a bounded grace period",
        "given": "an account marked deleted",
        "when": "the grace period for mistaken requests expires",
        "then": "the personal fields are overwritten or cryptographically shredded so no role can restore them, and any un-delete during the grace period requires the same verification and approval as the original request"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Downstream systems keep using deleted customers' data because they never hear about the deletion",
      "scenario": "The flag lives only in the main database, so warehouse-driven reports, marketing exports and anything built on the logs continue to include the customer. Deleted customers keep appearing in analytics and outbound messaging, disclosing their data to internal consumers and third parties who should no longer hold it, and the organisation cannot demonstrate that an erasure request was honoured.",
      "component": "Warehouse and log consumers",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        { "quote": "Copies in the warehouse, logs and backups are left as is." }
      ],
      "cwe": ["CWE-212"],
      "plainLanguage": "Reports and mailing lists built from the reporting database still include customers who asked to be deleted.",
      "requirement": {
        "title": "Publish deletion events to all data consumers",
        "given": "a deletion has been executed in the main database",
        "when": "downstream pipelines next run",
        "then": "they receive and apply the deletion event, exclude or purge the affected subject, and the deletion request is not closed until every registered consumer has acknowledged completion"
      }
    }
  ]
}
